#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long u64;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    vector<long long> a(n);
    for (auto &x : a) scanf("%lld", &x);
    if (n == 1) { puts("1"); return 0; }
    // Sieve primes below n and pack them into a bitset.
    vector<char> sieve(n, 1);
    sieve[0] = sieve[1] = 0;
    for (long long p = 2; p * p < n; p++)
        if (sieve[p])
            for (long long m = p * p; m < n; m += p) sieve[m] = 0;
    int W = (n + 63) / 64 + 2;
    vector<u64> primes(W, 0), reach(W, 0);
    for (int i = 2; i < n; i++)
        if (sieve[i]) primes[i >> 6] |= 1ULL << (i & 63);
    reach[0] = 1;
    // Process reachable positions in increasing order; OR the allowed prime steps shifted to i.
    for (int i = 0; i < n; i++) {
        if (!(reach[i >> 6] >> (i & 63) & 1)) {
            // skip whole empty words quickly
            int w = i >> 6;
            u64 rest = reach[w] >> (i & 63);
            if (rest == 0) {
                i = (w + 1) * 64 - 1;
            }
            continue;
        }
        if (i == n - 1) { puts("1"); return 0; }
        long long bound = min<long long>(a[i], n - 1 - i);
        if (bound < 2) continue;
        int lastWord = (int)(bound >> 6);
        int sh = i & 63, base = i >> 6;
        for (int k = 0; k <= lastWord; k++) {
            u64 p = primes[k];
            if (k == lastWord) {
                int b = (int)(bound & 63);
                p &= (b == 63) ? ~0ULL : ((1ULL << (b + 1)) - 1);
            }
            if (!p) continue;
            reach[base + k] |= p << sh;
            if (sh) reach[base + k + 1] |= p >> (64 - sh);
        }
        if (reach[(n - 1) >> 6] >> ((n - 1) & 63) & 1) { puts("1"); return 0; }
    }
    puts("0");
}

import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return null;
        ByteArrayOutputStream sb = new ByteArrayOutputStream();
        while (c != -1 && c > ' ') { sb.write(c); c = read(); }
        return sb.toString(java.nio.charset.StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        if (n == 1) { System.out.println(1); return; }
        // Sieve primes below n and pack them into a bitset.
        boolean[] composite = new boolean[n];
        composite[0] = composite[1] = true;
        for (long p = 2; p * p < n; p++)
            if (!composite[(int) p])
                for (long m = p * p; m < n; m += p) composite[(int) m] = true;
        int W = (n + 63) / 64 + 2;
        long[] primes = new long[W], reach = new long[W];
        for (int i = 2; i < n; i++) if (!composite[i]) primes[i >> 6] |= 1L << (i & 63);
        reach[0] = 1;
        // Process reachable positions in increasing order; OR the allowed prime steps shifted to i.
        for (int i = 0; i < n; i++) {
            if ((reach[i >> 6] >>> (i & 63) & 1) == 0) {
                int w = i >> 6;
                if ((reach[w] >>> (i & 63)) == 0) i = (w + 1) * 64 - 1;
                continue;
            }
            if (i == n - 1) { System.out.println(1); return; }
            long bound = Math.min(a[i], n - 1 - i);
            if (bound < 2) continue;
            int lastWord = (int) (bound >> 6);
            int sh = i & 63, base = i >> 6;
            for (int k = 0; k <= lastWord; k++) {
                long p = primes[k];
                if (k == lastWord) {
                    int b = (int) (bound & 63);
                    p &= (b == 63) ? -1L : ((1L << (b + 1)) - 1);
                }
                if (p == 0) continue;
                reach[base + k] |= p << sh;
                if (sh != 0) reach[base + k + 1] |= p >>> (64 - sh);
            }
            if ((reach[(n - 1) >> 6] >>> ((n - 1) & 63) & 1) != 0) { System.out.println(1); return; }
        }
        System.out.println(0);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := rd.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return ""
	}
	b := []byte{}
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		b = append(b, c)
		c, err = rd.ReadByte()
	}
	return string(b)
}

func main() {
	n := readInt()
	a := make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	if n == 1 {
		fmt.Println(1)
		return
	}
	// Sieve primes below n and pack them into a bitset.
	composite := make([]bool, n)
	composite[0], composite[1] = true, true
	for p := 2; p*p < n; p++ {
		if !composite[p] {
			for m := p * p; m < n; m += p {
				composite[m] = true
			}
		}
	}
	W := (n+63)/64 + 2
	primes := make([]uint64, W)
	reach := make([]uint64, W)
	for i := 2; i < n; i++ {
		if !composite[i] {
			primes[i>>6] |= 1 << uint(i&63)
		}
	}
	reach[0] = 1
	// Process reachable positions in increasing order; OR the allowed prime steps shifted to i.
	for i := 0; i < n; i++ {
		if reach[i>>6]>>uint(i&63)&1 == 0 {
			w := i >> 6
			if reach[w]>>uint(i&63) == 0 {
				i = (w+1)*64 - 1
			}
			continue
		}
		if i == n-1 {
			fmt.Println(1)
			return
		}
		bound := min(a[i], n-1-i)
		if bound < 2 {
			continue
		}
		lastWord := bound >> 6
		sh, base := uint(i&63), i>>6
		for k := 0; k <= lastWord; k++ {
			p := primes[k]
			if k == lastWord {
				b := uint(bound & 63)
				if b != 63 {
					p &= (uint64(1) << (b + 1)) - 1
				}
			}
			if p == 0 {
				continue
			}
			reach[base+k] |= p << sh
			if sh != 0 {
				reach[base+k+1] |= p >> (64 - sh)
			}
		}
		if reach[(n-1)>>6]>>uint((n-1)&63)&1 == 1 {
			fmt.Println(1)
			return
		}
	}
	fmt.Println(0)
